head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");

//#include("../js/controlResize.js"); // 화면 리사이징
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
scwin.vScrenID = "ULDINS20100.xml";
scwin.nPreRow = -1;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
/**
 *  화면 초기화
 */
scwin.fn_Init = function() {
    $c.cm.PanelToGroupBox(panel_1);
    $c.cm.PanelToGroupBox(panel_2);
    $c.stf.showObj(btn_delete, false);
    scwin.ins_Search();
};


/**
 *  데이터셋 초기화.
 */
scwin.fn_InitDs = function() {
    dts_CntrInfo.removeAll();
};


/**
 * 국가코드조회 조회
 */
scwin.ins_Search = function() {
    //데이터셋 초기화
    scwin.fn_InitDs();

    // 조회조건 체크.
    if (!scwin.fn_ChkValid("select")) {
        return;
    }

    // Lodaing~~~ 표시
    $c.cm.ShowWin(grd_CntrInfo);
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamic" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.etc.select.listEtcNatCdInfoInquiry" + "&outputMessageId=ULDINS20100_LIST_OUT" + "&param01=" + $c.stf.getObjectValue(txb_pCNTR_NM) + "&param02=" + $c.stf.getObjectValue(txb_pCNTR_ENG_NM) + "&param03=" + $c.stf.getObjectValue(txb_pCNTR_ENG_SRT_NM);
    dts_CntrInfo.DataID = encodeURI(url);
    dts_CntrInfo.Reset();
};


/**
 * 국가코드 입력
 */
scwin.ins_Insert = function() {
    // 사전체크
    if (!scwin.fn_ChkValid("insert")) {
        return;
    }
    if (!confirm("저장하시겠습니까?")) {
        return;
    }
    trs_Save.Action = "/EtcInfoAction.do?method=registerEtcNatCdInfo" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02 + "&queryId=lds.ins.etc.insert.registerEtcNatCdInfo";
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_CntrInfo)";
    trs_Save.Parameters = "EMP_NO=" + js_emp_no + ",EMP_NM=" + js_emp_nm;
    trs_Save.Post();
};


/**
 * 국가코드 수정
 */
scwin.ins_Update = function() {
    // 사전체크
    if (!scwin.fn_ChkValid("update")) {
        return;
    }
    if (!confirm("수정하시겠습니까?")) {
        return;
    }
    trs_Save.Action = "/EtcInfoAction.do?method=modifyEtcNatCdInfo" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03 + "&queryId=lds.ins.etc.update.modifyEtcNatCdInfo";
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_CntrInfo)";
    trs_Save.Parameters = "EMP_NO=" + js_emp_no + ",EMP_NM=" + js_emp_nm;
    trs_Save.Post();
};


/**
 * 사전체크
 */
scwin.fn_ChkValid = function(pGubun) {
    if (pGubun == undefined || pGubun == "select") {
        return true;
    }
    if ($c.stf.getObjectValue(edt_CNTR_CD) == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "국가코드(숫자 세자리)"));
        edt_CNTR_CD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_CNTR_CD).length != 3) {
        $c.win.alert("국가코드를 숫자 3자리로 입력하세요.");
        edt_CNTR_CD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_CNTR_CD2) == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "국가코드(문자 두자리)"));
        edt_CNTR_CD2.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_CNTR_CD2).length != 2) {
        $c.win.alert("국가코드를 문자 2자리로 입력하세요.");
        edt_CNTR_CD2.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_CNTR_CD3) == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "국가코드(문자 세자리)"));
        edt_CNTR_CD3.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_CNTR_CD3).length != 3) {
        $c.win.alert("국가코드를 문자 3자리로 입력하세요.");
        edt_CNTR_CD3.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_CNTR_NM) == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "국가명"));
        txb_CNTR_NM.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_CNTR_NM, 80, "국가명")) {
        //txb_COM_ENG_NM.value = "";
        txb_CNTR_NM.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_CNTR_ENG_NM, 60, "국가영문명")) {
        //txb_COM_ENG_NM.value = "";
        txb_CNTR_ENG_NM.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_CNTR_ENG_SRT_NM, 60, "국가영문약명")) {
        //txb_COM_ENG_NM.value = "";
        txb_CNTR_ENG_SRT_NM.focus();
        return false;
    }
    if (pGubun == "update") {
        if (!$c.cp.isModified(dts_CntrInfo)) {
            $c.win.alert("변경된 데이터가 없습니다.");
            return false;
        }

        // 수정가능 데이터인지 체크
        if (dts_CntrInfo.getCellData(dts_CntrInfo.getRowPosition(), "SELECTED") != "Y") {
            $c.win.alert("수정 대상 데이터가 아닙니다.");
            return false;
        }
    } else if (pGubun == "insert") {
        // 입력가능 데이터인지 체크
        if (dts_CntrInfo.getCellData(dts_CntrInfo.getRowPosition(), "SELECTED") == "Y") {
            $c.win.alert("신규등록 대상 데이터가 아닙니다.");
            return false;
        }

        // 국가코드 중복 체크.
        scwin.fn_DuplicateDChk();
        if (dts_DuplChk.getCellData(1, "CNT") > 0) {
            $c.win.alert("이미 등록된 국가코드 입니다.");
            return false;
        }
    }
    return true;
};


/**
 * 국가코드 중복체크
 */
scwin.fn_DuplicateDChk = function() {
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamic" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.etc.select.natCdDuplChk" + "&outputMessageId=INS_NAT_CD_DUPL_CHK" + "&param01=" + $c.stf.getObjectValue(edt_CNTR_CD);
    dts_DuplChk.DataID = encodeURI(url);
    dts_DuplChk.Reset();
};


/**
 * 국가코드 삭제
 */
scwin.ins_Delete = function() {
    if (!confirm("삭제하시겠습니까?")) {
        return;
    }
    //dts_Delete.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
    dts_Delete.insertRow();
    dts_Delete.setCellData(1, "CNTR_CD", dts_CntrInfo.getCellData(dts_CntrInfo.getRowPosition(), "CNTR_CD"));
    trs_Delete.Action = "/EtcInfoAction.do?method=removeEtcNatCdInfo" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04 + "&queryId=lds.ins.etc.delete.removeEtcNatCdInfo";
    trs_Delete.KeyName = "toinb_dataid4";
    trs_Delete.KeyValue = "JSP(I:pInput=dts_Delete)";
    trs_Delete.Post();
};


/**
 * 신규버튼 클릭
 */
scwin.fn_New = function() {
    dts_CntrInfo.insertRow();
    cmb_ACTIV_YN.setSelectedIndex(0);
    edt_CNTR_CD.focus();
};
scwin.gform_onload = function() {
    scwin.fn_Init();
};
scwin.dts_CntrInfo_OnLoadError = function() {
    $c.cm.CloseWin(-1, grd_CntrInfo);
    $c.stf.alert_error(dts_CntrInfo);
};
scwin.dts_CntrInfo_OnLoadCompleted = function(rowcount) {
    if (dts_CntrInfo.errorMsg) {
        $c.win.alert(dts_CntrInfo.errorMsg);
    } else {
        txb_TotalCnt.setValue("총 " + rowcount + "건");
    }
    $c.cm.CloseWin(rowcount, grd_CntrInfo);

    // 데이터가 없는 경우
    if (rowcount == 0) {
        fn_CtrlBtn_temp("no_data");
    }
};
scwin.btn_delete_onclick = function() {
    scwin.ins_Delete();
};
scwin.btn_modify_onclick = function() {
    scwin.ins_Update();
};
scwin.btn_save_onclick = function() {
    scwin.ins_Insert();
};
scwin.trs_Delete_OnSuccess = function() {
    //alert( getMessageParam("MSG-A001", "삭제") );
    $c.win.alert($c.stf.getMessageParam("MSG-0001"));
    // 재조회
    //ins_Search(); 

};
scwin.trs_Delete_OnFail = function() {
    alert_tr_error(trs_Delete);
};
scwin.trs_Save_OnFail = function() {
    alert_tr_error(trs_Save);
};
scwin.trs_Save_OnSuccess = function() {
    //alert( getMessageParam("MSG-A001", "저장") );
    $c.win.alert($c.stf.getMessageParam("MSG-0001"));

    // 재조회
    //ins_Search(); 

};
scwin.btn_new_onclick = function() {
    scwin.fn_New();
};
scwin.dts_CntrInfo_OnRowPosChanged = function(row) {
    dts_CntrInfo.undoRow(scwin.nPreRow);
    scwin.nPreRow = row;

    // 조회된 것들은 국가코드 비활성, 신규로 생성된 것만 활성.
    if (dts_CntrInfo.getCellData(row, "SELECTED") == "Y") {
        edt_CNTR_CD.setReadOnly(true);
        fn_CtrlBtn_temp("update");
    } else {
        edt_CNTR_CD.setReadOnly(false);
        fn_CtrlBtn_temp("insert");
    }
};
scwin.txb_CNTR_NM_onkeyup = function() {
    fn_DelChar(this);
};
scwin.btn_search_onclick = function() {
    scwin.ins_Search();
};
scwin.txb_pCNTR_ENG_SRT_NM_onkeyup = function() {
    fn_DelChar(this);
    if (txb_pCNTR_ENG_SRT_NM.getValue() == "") {

    } else {
        if (window.event.keyCode == 13) {
            scwin.ins_Search();
        }
    }
};
scwin.txb_pCNTR_NM_onkeyup = function() {
    fn_DelChar(this);
    if (txb_pCNTR_NM.getValue() == "") {

    } else {
        if (window.event.keyCode == 13) {
            scwin.ins_Search();
        }
    }
};
scwin.txb_pCNTR_ENG_NM_onkeyup = function() {
    fn_DelChar(this);
    if (txb_pCNTR_ENG_NM.getValue() == "") {

    } else {
        if (window.event.keyCode == 13) {
            scwin.ins_Search();
        }
    }
};
